package com.tradingplatform.persistence;
import com.tradingplatform.paper.*; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="paper_orders") public class PaperOrderEntity { @Id public UUID id; @Column(name="account_id") public UUID accountId; @Column(name="instrument_key") public String instrumentKey; public String symbol; @Enumerated(EnumType.STRING) public PaperSide side; public int quantity; @Column(name="requested_price") public BigDecimal requestedPrice; @Column(name="execution_price") public BigDecimal executionPrice; @Column(name="order_type") public String orderType; @Enumerated(EnumType.STRING) public PaperOrderStatus status; public BigDecimal charges; @Column(name="rejection_reason") public String rejectionReason; @Column(name="created_at") public Instant createdAt; @Column(name="filled_at") public Instant filledAt; }
